package service;

import domain.EarnEntry;
import domain.Member;
import domain.Payment;
import domain.RunResult;
import infra.PtsctlClient;
import store.EarnLedger;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * Daily earn run: every approved payment of a known member earns grade-rate
 * points at the points vendor once. The vendor reference is prefix + payment id,
 * so a re-run never earns twice.
 */
public class EarnBatchJob {
    private final MemberDirectory members;
    private final EarnPolicy policy;
    private final EarnLedger ledger;
    private final PtsctlClient pts;
    private final String refPrefix;

    public EarnBatchJob(MemberDirectory members, EarnPolicy policy, EarnLedger ledger, PtsctlClient pts,
                        String refPrefix) {
        this.members = members;
        this.policy = policy;
        this.ledger = ledger;
        this.pts = pts;
        this.refPrefix = refPrefix;
    }

    public RunResult run(LocalDate day, List<Payment> payments) {
        int earned = 0;
        int skipped = 0;
        long total = 0;
        List<String> unknown = new ArrayList<>();
        for (Payment p : PaymentDeduper.unique(payments)) {
            if (!p.approved() || ledger.contains(p.payId())) {
                skipped++;
                continue;
            }
            Optional<Member> m = members.find(p.memberNo());
            if (m.isEmpty()) {
                unknown.add(p.memberNo());
                continue;
            }
            long pts = policy.points(p.amount(), m.get().grade());
            if (pts == 0) {
                skipped++;
                continue;
            }
            String entryNo = this.pts.earn(m.get().memberNo(), pts, refPrefix + "-" + p.payId());
            ledger.record(new EarnEntry(p.payId(), m.get().memberNo(), pts, day, entryNo));
            earned++;
            total += pts;
        }
        return new RunResult(earned, total, List.copyOf(unknown), skipped);
    }
}
package infra;

import domain.Grade;
import domain.Member;
import domain.Payment;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/** Fixture/export readers. Values never contain commas. */
public final class CsvFiles {
    private CsvFiles() {}

    public static List<Member> members(Path file) {
        List<Member> out = new ArrayList<>();
        for (String[] r : rows(file)) {
            out.add(new Member(cell(r[0]), r[1], Grade.valueOf(r[2]), r[3]));
        }
        return out;
    }

    public static List<Payment> payments(Path file) {
        List<Payment> out = new ArrayList<>();
        for (String[] r : rows(file)) {
            out.add(new Payment(r[0], cell(r[1]), r[2], Long.parseLong(r[3]), r[4]));
        }
        return out;
    }

    /**
     * The acquirer's payment export is made for spreadsheets: member numbers that start
     * with 0 are written as ="004512" so the spreadsheet keeps them as text.
     */
    static String cell(String raw) {
        String s = raw.strip();
        if (s.startsWith("=\"") && s.endsWith("\"") && s.length() >= 3) {
            return s.substring(2, s.length() - 1);
        }
        if (s.length() >= 2 && s.startsWith("\"") && s.endsWith("\"")) {
            return s.substring(1, s.length() - 1);
        }
        return s;
    }

    private static List<String[]> rows(Path file) {
        try {
            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
            List<String[]> rows = new ArrayList<>();
            for (int i = 1; i < lines.size(); i++) {
                String l = lines.get(i).strip();
                if (!l.isEmpty()) rows.add(l.split(",", -1));
            }
            return rows;
        } catch (IOException e) {
            throw new IllegalStateException("cannot read " + file, e);
        }
    }
}
package service;

import domain.Member;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Member lookup. Keys are the member number exactly as issued (text, not a number). */
public class MemberDirectory {
    private final Map<String, Member> members = new LinkedHashMap<>();

    public MemberDirectory(List<Member> list) {
        for (Member m : list) {
            String key = key(m.memberNo());
            if (members.putIfAbsent(key, m) != null) {
                throw new IllegalStateException("member number issued twice: " + m.memberNo());
            }
        }
    }

    public Optional<Member> find(String memberNo) {
        return Optional.ofNullable(members.get(key(memberNo)));
    }

    public List<Member> all() {
        return List.copyOf(members.values());
    }

    /** Corporate codes are case-insensitive on the acquirer side ("c7781" == "C7781"). */
    static String key(String memberNo) {
        return memberNo.strip().toUpperCase();
    }
}
